//! 🧪️ Original tick columns remain unchanged while a separately funded empty successor inherits exact continuation metadata.
use super::*;
use semio_framework_value::{retained_clone::{RetainedCloneGrant,RetainedCloneProgress},retirement::controlled::ControlledRetirement};
fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
#[test]
fn original_tick_successor_preserves_original_native_columns_and_zero_metadata_receipt(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let p=&law["policy"];let grant=RetainedCloneGrant{maximum_items:p["items"].as_u64().unwrap()as usize,maximum_copy_bytes:p["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:p["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:p["release"].as_u64().unwrap()as usize,maximum_depth:p["depth"].as_u64().unwrap()as usize};
 for row in law["cases"].as_array().unwrap(){let(original,birth)=observe(||{let mut writer=ToolRunTickWriter::new(ToolRunIdentity::new(ToolRunId{app_instance_id:7,run:11},[17;32]));writer.next_sequence=row["sequence"].as_u64().unwrap();writer.next_page=row["page"].as_u64().unwrap()as u32;writer.next_step=row["step"].as_u64().unwrap();writer.provisional_base=row["base"].as_u64().unwrap()as u32;writer.append_ops=(0..row["appends"].as_u64().unwrap()).map(|i|vec![i as u8]).collect();writer.payload=Some(vec![0;8192]);if row["pendingPage"].as_bool().unwrap(){writer.page_ops.push(ToolRunTraceOp::Clear);}writer});let pointer=&original as*const _;let columns=original.append_ops.as_ptr();let payload=original.payload.as_ref().unwrap().as_ptr();
  for denied in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(result,heap)=observe(||original.admit_original_successor(denied).unwrap());assert!(result.is_none());assert_eq!(heap,(0,0));assert_eq!(&original as*const _,pointer);assert_eq!(original.append_ops.as_ptr(),columns);assert_eq!(original.payload.as_ref().unwrap().as_ptr(),payload);}
  let((successor,progress),heap)=observe(||original.admit_original_successor(grant).unwrap().unwrap());assert_eq!(heap,(0,0));assert_eq!(progress,RetainedCloneProgress{copied_items:1,..Default::default()});assert!(progress.fits(grant));assert_eq!(successor.next_sequence,row["sequence"].as_u64().unwrap()+1);assert_eq!(successor.next_page,row["page"].as_u64().unwrap()as u32+u32::from(row["pendingPage"].as_bool().unwrap()));assert_eq!(successor.next_step,original.next_step);assert_eq!(successor.provisional_base,original.provisional_base+original.append_ops.len()as u32);assert!(successor.is_empty());assert_eq!(original.append_ops.as_ptr(),columns);assert_eq!(original.payload.as_ref().unwrap().as_ptr(),payload);
  let mut original=ControlledRetirement::new(original).ok().unwrap();let mut born=birth.0;let mut released=birth.1;let mut turns=0;while !original.terminal_is_empty(){let(step,heap)=observe(||original.step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),heap);born+=heap.0;released+=heap.1;turns+=1;assert!(turns<100000);}assert_eq!(born,released);let((),heap)=observe(||{drop(original);drop(successor);});assert_eq!(heap,(0,0));println!("[DEBUG] original tick successor appends={} sameOriginalColumns metadataCopy0 heap0 original5axis grant physical={released} closeTurns={turns} terminalDrop0",row["appends"]);
 }
}
